// Bundled score library. Score JSON lives in public/scores (generated by
// scripts/build-scores.ts from score-src/) and is loaded from the app's own
// origin — never from a remote server.
import { validateScore, type ScoreData } from './score.ts';

export const SONG_IDS = ['canon-in-d', 'fur-elise', 'ode-to-joy', 'rondo-alla-turca', 'prelude-c-major', 'mountain-king', 'eine-kleine', 'brandenburg-1'] as const;

export interface UnavailablePiece {
  title: string;
  reason: string;
}

export const UNAVAILABLE: UnavailablePiece[] = [
  {
    title: 'Beethoven — Piano Sonata No. 14 “Moonlight”, Op. 27 No. 2, I. Adagio sostenuto',
    reason: 'The only machine-readable typesetting found (Mutopia #276) is licensed CC BY-SA 2.5. A share-alike source was not bundled; no verified public-domain or attribution-only note data was available, so the piece is disabled rather than reconstructed from memory.',
  },
  {
    title: 'Vivaldi — The Four Seasons, “Spring” (La primavera), RV 269, I. Allegro',
    reason: 'The typesetting found (Mutopia #301) is licensed CC BY-SA 3.0. As above, it is listed but disabled until a verified public-domain or attribution-only source is added.',
  },
];

const cache = new Map<string, ScoreData>();

export async function loadScore(id: string): Promise<ScoreData> {
  const hit = cache.get(id);
  if (hit) return hit;
  const res = await fetch(`./scores/${id}.json`, { cache: 'force-cache' });
  if (!res.ok) throw new Error(`Score ${id} could not be loaded (${res.status}).`);
  const data: unknown = await res.json();
  const errs = validateScore(data);
  if (errs.length) throw new Error(`Score ${id} failed validation: ${errs[0]}`);
  cache.set(id, data as ScoreData);
  return data as ScoreData;
}

export async function loadLibrary(): Promise<{ scores: ScoreData[]; errors: string[] }> {
  const errors: string[] = [];
  const scores: ScoreData[] = [];
  await Promise.all(
    SONG_IDS.map(async (id) => {
      try {
        scores.push(await loadScore(id));
      } catch (e) {
        errors.push(e instanceof Error ? e.message : String(e));
      }
    }),
  );
  scores.sort((a, b) => SONG_IDS.indexOf(a.id as (typeof SONG_IDS)[number]) - SONG_IDS.indexOf(b.id as (typeof SONG_IDS)[number]));
  return { scores, errors };
}

export function getScore(id: string): ScoreData | undefined {
  return cache.get(id);
}

/** Register an imported, already-validated score (session only; never executed). */
export function registerScore(s: ScoreData): void {
  cache.set(s.id, s);
}

export function allScores(): ScoreData[] {
  const order = (id: string) => {
    const i = SONG_IDS.indexOf(id as (typeof SONG_IDS)[number]);
    return i < 0 ? 100 : i;
  };
  return [...cache.values()].sort((a, b) => order(a.id) - order(b.id));
}

export function songLabel(s: ScoreData): string {
  return `${s.title} — ${s.composer.split(' ').slice(-1)[0]}`;
}
